-- Daily challenges for 2026-10-05: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-05

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('thanking-people-at-work', 'Thanking People at Work', 'For anyone who means to say thank you at work and rarely gets around to it. Each day is one small, specific way to notice what coworkers, managers, customers and the people behind the scenes do, and tell them, so work feels a little warmer for everyone.', 'Work', 365, array['Work', 'Relationships']::text[], 1, '2026-10-05T17:00:00+00:00'::timestamptz),
  ('making-friends-as-an-adult', 'Making Friends as an Adult', 'For grown-ups who would like more friends but are not sure where to start once school is behind them. Each day is one small, low-pressure step toward meeting people, following up, and letting an acquaintance slowly become a friend.', 'Connection', 365, array['Loneliness', 'Relationships', 'Social Anxiety']::text[], 1, '2026-10-05T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('thanking-people-at-work', 'making-friends-as-an-adult');

